#!/usr/bin/env python3
"""NanoBioMat V0.3 — educational magnetic models, not a validated fitting suite.
Run: python magnetism_reference.py --out results
Requires numpy, scipy, matplotlib. No network access or experimental data required.
SI: K in J/m3, Ms in A/m, B=mu0 H in tesla. Lognormal NUMBER distribution;
M/Ms is V-weighted. Effective positive uniaxial K, not cubic magnetite K1.
SW energy tables are embedded below and generated by work/generate.py.
Thermal two-well approximation omits intrawell fluctuations, interactions,
Brownian rotation, temperature dependence of Ms/K and finite-field rate prefactors.
Use with caution for KV/kBT < 5. The synthetic fitting demo fits K ONLY with
known V distribution and tau0; relaxation alone does not identify K and V separately.
References: Stoner/Wohlfarth 1948 doi:10.1098/rsta.1948.0007;
Tournus/Bonet 2011 doi:10.1016/j.jmmm.2010.11.056 (and corrigendum);
Tournus/Tamion 2011 doi:10.1016/j.jmmm.2010.11.057;
Hillion et al. 2013 doi:10.1103/PhysRevB.88.094419.
This implementation is NOT the authors' published software.
"""
import argparse,base64,zlib,json
from pathlib import Path
import numpy as np
KB=1.380649e-23;MS=480000.;TAU0=1e-9
DATA=''
TABLE=np.array(json.loads(zlib.decompress(base64.b64decode(DATA)))['table'])
def sizes(d,sigma):
 z=np.linspace(-3.5,3.5,25);n=np.exp(-z*z/2)
 v=np.pi/6*(d*1e-9*np.exp(sigma*z))**3;w=n*v;return v[:,None],(w/w.sum())[:,None]/32

def row(h):return TABLE[int(np.clip(np.floor((h+1.2)*100+.5),0,240))]
def update(p,r,K,v,T,dt):
 if T==0:q=p.copy()
 else:
  a=.5/TAU0*np.exp(-K*v*r[:,5]/(KB*T));b=.5/TAU0*np.exp(-K*v*r[:,6]/(KB*T))
  rate=a+b;eq=np.divide(b,rate,out=np.full_like(b,.5),where=rate>1e-100)
  q=eq+(p-eq)*np.exp(-rate*dt)
 return np.where(r[:,0]==1,r[:,1],q)
def mean(p,r,w):return np.sum(w*np.where(r[:,0]==1,r[:,2],p*r[:,1]+(1-p)*r[:,2]))
def run(path,K=20000,d=16,sigma=.12,T=100,dt=1,initial=.5):
 v,w=sizes(d,sigma);p=np.full((25,32),initial);out=[]
 for h in path:
  r=row(h);p=update(p,r,K,v,T,dt);out.append(mean(p,r,w))
 return np.array(out)
def zfcfc(K=20000,d=16,sigma=.12,secK=2):
 v,w=sizes(d,sigma);r=row(.02);ts=np.linspace(5,400,159)
 eq=1/(1+np.exp(np.clip(K*v*(r[:,6]-r[:,5])/(KB*400),-700,700)))
 eq=np.where(r[:,0]==1,r[:,1],eq)
 out=[]
 for temps,p in [(ts,np.full((25,32),.5)),(ts[::-1],eq)]:
  vals=[]
  for temp in temps:p=update(p,r,K,v,temp,secK*2.5);vals.append(mean(p,r,w))
  out.append(np.column_stack([temps,vals]))
 return out

def remtime(K=20000,d=16,sigma=.12,T=100,hp=.5):
 v,w=sizes(d,sigma);times=np.logspace(-6,5,112);out=[]
 paths=[np.r_[np.linspace(0,hp,61),np.linspace(hp,0,61)],np.r_[np.linspace(1.2,-hp,121),np.linspace(-hp,0,61)]]
 for path,initial in zip(paths,[.5,1.]):
  p=np.full((25,32),initial)
  for h in path:p=update(p,row(h),K,v,T,.1)
  vals=[mean(update(p,row(0),K,v,T,t),row(0),w) for t in times]
  out.append(np.column_stack([times,vals]))
 return out

def relaxation(t,K,d=16,sigma=.12,T=100):
 v,w=sizes(d,sigma);logtau=np.log(TAU0)+K*v[:,0]/(KB*T)
 return np.sum((w[:,0]*32)[:,None]*np.exp(-np.exp(np.minimum(700,np.log(t)[None,:]-logtau[:,None]))),axis=0)

def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--out',default='magnetism-results');args=ap.parse_args();out=Path(args.out);out.mkdir(parents=True,exist_ok=True)
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 from scipy.optimize import least_squares
 fig,ax=plt.subplots(2,3,figsize=(14,8),layout='constrained');ax=ax.ravel()
 path=np.r_[np.linspace(1.2,-1.2,241),np.linspace(-1.2,1.2,241)];m=run(path,T=0,initial=1)
 assert abs(m[120]-.5)<1e-5;assert abs(m[361]+.5)<1e-5
 np.savetxt(out/'sw-loop.csv',np.c_[path,m],delimiter=',',header='H_over_HK,M_over_Ms')
 ax[0].plot(path,m);ax[0].set(xlabel='H/HK',ylabel='M/Ms',title='SW, random 3D axes, T=0')
 z,f=zfcfc();np.savetxt(out/'zfc.csv',z,delimiter=',',header='T_K,M_over_Ms');np.savetxt(out/'fc.csv',f,delimiter=',',header='T_K,M_over_Ms')
 ax[1].plot(*z.T,label='ZFC');ax[1].plot(*f.T,label='FC');ax[1].set(xlabel='T (K)',ylabel='M/Ms',title='Thermal two-well approximation');ax[1].legend()
 for T in [20,100,200]:
  h=np.linspace(0,1.2,121);m=run(h,T=T,dt=(2*20000/MS)*.01/.001)
  np.savetxt(out/f'initial-{T}K.csv',np.c_[h*(2*20000/MS)*1000,m],delimiter=',',header='mu0H_mT,M_over_Ms')
  ax[2].plot(h*(2*20000/MS)*1000,m,label=f'{T} K')
 ax[2].set(xlabel='mu0 H (mT)',ylabel='M/Ms',title='Initial magnetization, 1 mT/s');ax[2].legend()
 h=np.linspace(0,1.2,121);w=np.exp(-.5*((h-.45)/.12)**2);w[0]=0;irm=np.cumsum(w)/w.sum();dcd=1-2*irm
 np.savetxt(out/'remanence.csv',np.c_[h,irm,dcd,np.zeros_like(h)],delimiter=',',header='H_over_H0,mIRM,mDCD,deltaM')
 ax[3].plot(h,irm,label='IRM');ax[3].plot(h,dcd,label='DCD');ax[3].plot(h,h*0,label='delta M');ax[3].set(xlabel='|H|/H0',ylabel='M/Mrs',title='Independent symmetric hysterons');ax[3].legend()
 rt=remtime()
 for name,data in zip(['IRM','DCD'],rt):np.savetxt(out/f'{name}-time.csv',data,delimiter=',',header='t_s,M_over_Ms');ax[4].semilogx(*data.T,label=name)
 ax[4].set(xlabel='t (s)',ylabel='M/Ms',title='Zero-field relaxation after preparation');ax[4].legend()
 c=np.arange(.01,1.011,.025);u=np.arange(-.5,.501,.025);C,U=np.meshgrid(c,u);density=np.exp(-.5*((C-.45)/.12)**2-.5*(U/.08)**2);w=density/density.sum()
 lines=[]
 for hr in np.linspace(-1.2,.2,15):
  h=np.linspace(hr,1.5,100);m=np.array([np.sum(w*np.where((hr<=U-C)&(v<U+C),-1,1)) for v in h]);ax[5].plot(h,m,lw=.8);lines.extend(zip(np.repeat(hr,len(h)),h,m))
 np.savetxt(out/'forc-family.csv',lines,delimiter=',',header='Hr_over_H0,H_over_H0,M_over_Ms')
 ax[5].set(xlabel='H/H0',ylabel='M/Ms',title='Illustrative Preisach FORCs')
 for a in ax:a.grid(alpha=.2)
 fig.savefig(out/'magnetism-models.png',dpi=160)
 # Synthetic inverse problem: only K fitted; all other parameters assumed known.
 t=np.logspace(-3,5,200);rng=np.random.default_rng(42);observed=relaxation(t,20000)+rng.normal(0,.002,len(t))
 fit=least_squares(lambda x:(relaxation(t,x[0]) - observed)/.002,[18000],bounds=([5000],[40000]))
 result={'MR_MS':.5,'synthetic_K_true_Jm3':20000,'synthetic_K_fit_Jm3':float(fit.x[0]),'not_experimental':True,'fixed_d_nm':16,'fixed_sigma':.12,'fixed_tau0_s':TAU0,'caution':'No independent identification of K and V from relaxation alone; synthetic test is not experimental validation.'}
 (out/'checks-and-synthetic-fit.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
if __name__=='__main__':main()
